import {BrowserRouter, Route} from 'react-router-dom';
const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  // <React.StrictMode> 
    <BrowserRouter>
      <Route exact path="/" component={App} />
      <App />
    </BrowserRouter>
